$(document).ready(function(){"undefined"!=typeof _WidgetManager&&"item"===_WidgetManager._GetAllData().blog.pageType&&window.auth.onAuthStateChanged(t=>{t&&async function(t){let e=null;"undefined"!=typeof _WidgetManager&&_WidgetManager._GetAllData().blog.postId&&(e=_WidgetManager._GetAllData().blog.postId);if(!e){const t=$(".blog-posts article.post, .blog-posts .post-outer").first();t.length&&(e=t.attr("data-post-id"))}const o=document.title,l=window.location.href.split("?")[0];if(e&&window.db){console.log("DEBUG Ghi Lịch Sử: Post ID = "+e);try{await window.db.collection("users").doc(t.uid).collection("viewedHistory").doc(e).set({postId:e,title:o,url:l,timestamp:firebase.firestore.FieldValue.serverTimestamp()},{merge:!0}),console.log("Đã lưu lịch sử xem thành công cho ID: "+e)}catch(t){console.error("Lỗi lưu lịch sử xem (Kiểm tra Security Rules):",t)}}else console.log("DEBUG Ghi Lịch Sử: Không tìm thấy Post ID hoặc DB chưa sẵn sàng.")}(t)})});